namespace {
void u16(QByteArray& b,quint16 v){b.append(char(v));b.append(char(v>>8));}
void u32(QByteArray& b,quint32 v){u16(b,v&0xffff);u16(b,v>>16);}
quint32 crc32(const QByteArray& data){quint32 c=0xffffffff;for(auto byte:data){c^=quint8(byte);for(int i=0;i<8;i++)c=(c>>1)^(0xedb88320&-(c&1));}return ~c;}
QString esc(const QString& s){return s.toHtmlEscaped();}
QString column(int index){QString out;do{out.prepend(QChar('A'+index%26));index=index/26-1;}while(index>=0);return out;}
const QByteArray rels=R"(<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="TARGET"/></Relationships>)";
}
QByteArray Export::zip(const QList<QPair<QString,QByteArray>>& files){QByteArray out,central;for(const auto& file:files){auto name=file.first.toUtf8(),body=file.second;quint32 offset=out.size(),crc=crc32(body);u32(out,0x04034b50);u16(out,20);u16(out,0x800);u16(out,0);u16(out,0);u16(out,0x21);u32(out,crc);u32(out,body.size());u32(out,body.size());u16(out,name.size());u16(out,0);out+=name;out+=body;u32(central,0x02014b50);u16(central,20);u16(central,20);u16(central,0x800);u16(central,0);u16(central,0);u16(central,0x21);u32(central,crc);u32(central,body.size());u32(central,body.size());u16(central,name.size());u16(central,0);u16(central,0);u16(central,0);u16(central,0);u32(central,0);u32(central,offset);central+=name;}auto start=out.size();out+=central;u32(out,0x06054b50);u16(out,0);u16(out,0);u16(out,files.size());u16(out,files.size());u32(out,central.size());u32(out,start);u16(out,0);return out;}
QByteArray Export::word(const Capture& d){QString xml=QStringLiteral("<?xml version=\"1.0\" encoding=\"UTF-8\"?><w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\"><w:body>");for(const auto& line:d.text.split('\n'))xml+="<w:p><w:r><w:rPr><w:rFonts w:eastAsia=\"Microsoft YaHei\"/><w:sz w:val=\"22\"/></w:rPr><w:t xml:space=\"preserve\">"+esc(line)+"</w:t></w:r></w:p>";
 if(!d.table.isEmpty()){xml+="<w:tbl><w:tblPr><w:tblW w:w=\"5000\" w:type=\"pct\"/><w:tblBorders><w:top w:val=\"single\" w:sz=\"4\"/><w:left w:val=\"single\" w:sz=\"4\"/><w:bottom w:val=\"single\" w:sz=\"4\"/><w:right w:val=\"single\" w:sz=\"4\"/><w:insideH w:val=\"single\" w:sz=\"4\"/><w:insideV w:val=\"single\" w:sz=\"4\"/></w:tblBorders></w:tblPr>";int columns=0;for(const auto& r:d.table)columns=qMax(columns,int(r.size()));xml+="<w:tblGrid>";for(int i=0;i<columns;i++)xml+="<w:gridCol w:w=\"2400\"/>";xml+="</w:tblGrid>";for(const auto& row:d.table){xml+="<w:tr>";for(int i=0;i<columns;i++)xml+="<w:tc><w:tcPr><w:tcW w:w=\"2400\" w:type=\"dxa\"/></w:tcPr><w:p><w:r><w:t xml:space=\"preserve\">"+esc(row.value(i))+"</w:t></w:r></w:p></w:tc>";xml+="</w:tr>";}xml+="</w:tbl>";}xml+="<w:sectPr><w:pgSz w:w=\"11906\" w:h=\"16838\"/><w:pgMar w:top=\"1440\" w:right=\"1440\" w:bottom=\"1440\" w:left=\"1440\"/></w:sectPr></w:body></w:document>";
 QByteArray root=rels;root.replace("TARGET","word/document.xml");return zip({{"[Content_Types].xml",R"(<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>)"},{"_rels/.rels",root},{"word/document.xml",xml.toUtf8()}});}
QByteArray Export::excel(const QList<QStringList>& table){QString xml="<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols><col min=\"1\" max=\"128\" width=\"22\" customWidth=\"1\"/></cols><sheetData>";
 for(int r=0;r<table.size();r++){xml+="<row r=\""+QString::number(r+1)+"\">";for(int c=0;c<table[r].size();c++)xml+="<c r=\""+column(c)+QString::number(r+1)+"\" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+esc(table[r][c])+"</t></is></c>";xml+="</row>";}xml+="</sheetData></worksheet>";
 QByteArray root=rels;root.replace("TARGET","xl/workbook.xml");return zip({{"[Content_Types].xml",R"(<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>)"},{"_rels/.rels",root},{"xl/workbook.xml",R"(<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="识别表格" sheetId="1" r:id="rId1"/></sheets></workbook>)"},{"xl/_rels/workbook.xml.rels",R"(<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>)"},{"xl/worksheets/sheet1.xml",xml.toUtf8()}});}
bool Export::pdf(const QString& path,const QImage& image,QString* error){if(image.isNull()){if(error)*error=QStringLiteral("没有可导出的图像");return false;}QPdfWriter writer(path);writer.setTitle(QStringLiteral("萌知 截图"));writer.setCreator("Mengzhi");writer.setResolution(96);writer.setPageSize(QPageSize(QSizeF(image.width()*25.4/96,image.height()*25.4/96),QPageSize::Millimeter));writer.setPageMargins(QMarginsF(0,0,0,0));QPainter p;if(!p.begin(&writer)){if(error)*error=QStringLiteral("无法写入 PDF 文件");return false;}p.drawImage(QRect(0,0,writer.width(),writer.height()),image);return p.end();}
QList<QStringList> Export::inferTable(const QVector<OcrBlock>& input){auto blocks=input;std::sort(blocks.begin(),blocks.end(),[](const auto&a,const auto&b){return a.bounds.y()<b.bounds.y();});QList<QVector<OcrBlock>> rows;QVector<double> anchors;for(const auto& b:blocks){bool found=false;for(auto& row:rows){if(qAbs(row[0].bounds.center().y()-b.bounds.center().y())<qMax(row[0].bounds.height(),b.bounds.height())*.6){row.push_back(b);found=true;break;}}if(!found)rows.push_back({b});bool anchor=false;for(auto x:anchors)if(qAbs(x-b.bounds.x())<.035)anchor=true;if(!anchor)anchors.push_back(b.bounds.x());}std::sort(anchors.begin(),anchors.end());QList<QStringList> result;for(auto row:rows){if(anchors.size()>32){std::sort(row.begin(),row.end(),[](auto&a,auto&b){return a.bounds.x()<b.bounds.x();});QStringList cells;for(const auto& b:row)cells<<b.text;result<<cells;}else{QStringList cells;for(int i=0;i<anchors.size();i++)cells<<QString();for(const auto& b:row){int best=0;for(int i=1;i<anchors.size();i++)if(qAbs(anchors[i]-b.bounds.x())<qAbs(anchors[best]-b.bounds.x()))best=i;if(!cells[best].isEmpty())cells[best]+=' ';cells[best]+=b.text;}result<<cells;}}return result;}
